 3	public final class BubbleSort {
 4	    private static final char VALUE_SEPARATOR = ' ';
 5	
 6	    private BubbleSort() {
 7	        // Utility class.
 8	    }
 9	
10	    public static void sort(int[] values) {
11	        Objects.requireNonNull(values, "values");
12	
13	        if (hasFewerThanTwoValues(values)) {
14	            return;
15	        }
16	
17	        for (int lastUnsortedIndex = values.length - 1; lastUnsortedIndex > 0; lastUnsortedIndex--) {
18	            if (!bubbleLargestValueToEnd(values, lastUnsortedIndex)) {
19	                return;
20	            }
21	        }
22	    }
23	
24	    public static int[] sortedCopy(int[] values) {
25	        Objects.requireNonNull(values, "values");
26	
27	        int[] sortedValues = values.clone();
28	        sort(sortedValues);
29	        return sortedValues;
30	    }
31	
32	    public static void printArray(int[] values) {
33	        System.out.println(toDisplayString(values));
34	    }
35	
36	    public static String toDisplayString(int[] values) {
37	        Objects.requireNonNull(values, "values");
38	
39	        StringBuilder output = new StringBuilder();
40	
41	        for (int value : values) {
42	            if (!output.isEmpty()) {
43	                output.append(VALUE_SEPARATOR);
44	            }
45	            output.append(value);
46	        }
47	
48	        return output.toString();
49	    }
50	
51	    private static boolean hasFewerThanTwoValues(int[] values) {
52	        return values.length < 2;
53	    }
54	
55	    private static boolean bubbleLargestValueToEnd(int[] values, int lastUnsortedIndex) {
56	        boolean swapped = false;
57	
58	        for (int currentIndex = 0; currentIndex < lastUnsortedIndex; currentIndex++) {
59	            if (values[currentIndex] > values[currentIndex + 1]) {
60	                swap(values, currentIndex, currentIndex + 1);
61	                swapped = true;
62	            }
63	        }
64	
65	        return swapped;
66	    }
67	
68	    private static void swap(int[] values, int leftIndex, int rightIndex) {
69	        int temporary = values[leftIndex];
70	        values[leftIndex] = values[rightIndex];
71	        values[rightIndex] = temporary;
72	    }
73	}

